# COPY — generated by build_repo_mirror.R. Do not edit here. Working copy: data_workspace_2026-07/parliamentary_dislocation/17_lords_official_rebuild.R
# 17_lords_official_rebuild.R — rebuild the Lords panel on the OFFICIAL parliament.uk series.
#
# WHY: 11_lords_panel.R spliced three sources (UCL per-session pages 2005-2026; Russell & Sciara
# for 1999-2005; a press report for 1997-98) and filled 1979-2004 with three FLAT sub-period
# averages (13 / 38 / 47.2). PJ manually downloaded the official parliament.uk series on 3 Aug
# 2026 (403-blocked to automated fetch) — it covers ALL 48 sessions 1975-76 to 2024-2026 on ONE
# consistent definition (a division in which the tellers on the losing side were Government Whips),
# so the splice and all three flat plateaus can go.
#
# Non-destructive: writes ONLY into lords_official_rebuild/. Nothing existing is overwritten.
suppressMessages({library(dplyr); library(ggplot2); library(patchwork)})
PROJECT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), "../..")) else getwd()
})
WS <- file.path(PROJECT, "data_workspace_2026-07")
setwd(file.path(WS, "parliamentary_dislocation"))
source(file.path(WS, "chow_standardized", "chow_test.R"))
dir.create("lords_official_rebuild", showWarnings=FALSE)
START <- 1979; END <- 2026

off <- read.csv("sources_raw/lords_defeats_by_session_official.csv", stringsAsFactors=FALSE)
off$start <- as.integer(substr(off$session, 1, 4))
off <- off[order(off$start),]

# The two sessions starting in 2019 (the days-long 2019-2019 session = 1 defeat, and 2019-2021 =
# 114) are merged, exactly as 11_lords_panel.R did: both start in calendar 2019.
off <- off |> group_by(start) |>
  summarise(defeats=sum(defeats), government=first(government), .groups="drop") |>
  arrange(start) |> as.data.frame()

# Session DURATION in years = gap to the next session's start. This is the fix for the fact that
# some sessions are ~2 years long (2010-12, 2019-21, 2024-26) and one was days (2019).
off$dur <- c(diff(off$start), 2)   # 2024-2026 runs Sept 2024 - Apr 2026
off$per_year <- off$defeats / off$dur

cat("=== Official series, by session ===\n"); print(off, row.names=FALSE)

# ---- annualise, step-carry keyed on session start year (project-standard convention) ----
carry <- function(vals, starts) {
  out <- rep(NA_real_, length(START:END)); yrs <- START:END
  for (i in seq_along(starts)) {
    nxt  <- if (i < length(starts)) starts[i+1] else END + 1
    fill <- starts[i]:(nxt-1); fill <- fill[fill >= START & fill <= END]
    out[yrs %in% fill] <- vals[i]
  }
  out
}
yrs <- START:END
lords <- data.frame(year=yrs,
                    raw   = carry(off$defeats,  off$start),   # like-for-like with the old panel
                    rate  = carry(off$per_year, off$start))   # duration-normalised

old <- read.csv("lords_defeats_annual.csv") |> select(year, old=lords_defeats)
cmp <- merge(lords, old, by="year", all.x=TRUE)
cat("\n=== Old (spliced+flat) vs new (official) ===\n"); print(cmp, row.names=FALSE)
write.csv(cmp, "lords_official_rebuild/lords_defeats_annual_official.csv", row.names=FALSE)

# ---- rerun the three-way PCA + Chow under each Lords variant ----
cowley <- read.csv(file.path(PROJECT,"data_may2026","data","processed","rebellions_annual.csv")) |>
  select(year, cowley_rate = rebellion_pct)
instab <- read.csv("parliamentary_dislocation_index.csv") |> select(year, instability = dislocation_index)

run_pca <- function(lords_vec, label) {
  d <- Reduce(function(x,y) merge(x,y,by="year",all=TRUE),
              list(cowley, instab, data.frame(year=yrs, lords_defeats=lords_vec)))
  d <- d[d$year>=START & d$year<=END,]; cc <- d[complete.cases(d),]
  Z <- as.data.frame(scale(cc[,c("cowley_rate","instability","lords_defeats")]))
  pc <- prcomp(Z, scale.=FALSE)
  pc1 <- pc$x[,1]; if (cor(pc1, cc$instability) < 0) pc1 <- -pc1
  cc$pc1 <- pc1
  ve <- summary(pc)$importance["Proportion of Variance",]
  sb <- chow_sweep(cc$year, cc$pc1)
  cat(sprintf("\n--- %s ---\n  n=%d  PC1 var=%.1f%%  loadings: %s\n  Chow: peak %d, F(2,%d)=%.2f, perm p=%.4f\n",
      label, nrow(cc), ve[1]*100,
      paste(sprintf("%s=%.2f", rownames(pc$rotation), pc$rotation[,1]), collapse=", "),
      sb$peak_year, sb$n-4, sb$peak_F, sb$perm_p))
  list(cc=cc, sb=sb, ve=ve, pc=pc)
}

cat("\n\n=== PCA / break comparison ===\n")
r_old  <- run_pca(old$old[match(yrs, old$year)], "OLD  (spliced + flat plateaus)")
r_raw  <- run_pca(lords$raw,  "NEW  (official, raw session counts)")
r_rate <- run_pca(lords$rate, "NEW  (official, per-year normalised)")

saveRDS(list(old=r_old, raw=r_raw, rate=r_rate), "lords_official_rebuild/_pca_variants.rds")

# ---- comparison figure ----
house <- theme_minimal(base_size=10) +
  theme(panel.grid.minor=element_blank(), panel.grid.major.x=element_blank(), legend.position="none",
        plot.subtitle=element_text(face="italic", colour="grey30", size=9),
        plot.tag=element_text(face="bold", size=11), axis.title=element_text(size=9, colour="grey20"))
xa <- list(scale_x_continuous(breaks=seq(1980,END,5)), coord_cartesian(xlim=c(START,END)))

pcmp <- ggplot(cmp, aes(year)) +
  geom_line(aes(y=old), colour="grey65", linewidth=0.9) +
  geom_line(aes(y=raw), colour="black", linewidth=0.7) +
  geom_point(aes(y=raw), colour="black", size=1.1) +
  xa + labs(tag="A", x=NULL, y="Defeats in the Lords",
    subtitle="Panel C, old (grey: spliced, flat before 2005) vs new (black: official, all sessions)") + house

prate <- ggplot(cmp, aes(year, rate)) +
  geom_line(colour="black", linewidth=0.7) + geom_point(colour="black", size=1.1) +
  xa + labs(tag="B", x=NULL, y="Defeats per year",
    subtitle="Official series normalised by session length") + house

pc1cmp <- ggplot() +
  geom_hline(yintercept=0, colour="grey70", linewidth=0.4) +
  geom_line(data=r_old$cc,  aes(year, pc1), colour="grey65", linewidth=0.9) +
  geom_line(data=r_rate$cc, aes(year, pc1), colour="black",  linewidth=0.7) +
  xa + labs(tag="C", x=NULL, y="PC1 (z)",
    subtitle="Combined PC1, old (grey) vs new normalised (black)") + house

pchow <- ggplot() +
  geom_hline(yintercept=r_rate$sb$crit_5pct, linetype="dashed", colour="grey55", linewidth=0.5) +
  geom_line(data=r_old$sb$curve,  aes(year, F), colour="grey65", linewidth=0.9) +
  geom_line(data=r_rate$sb$curve, aes(year, F), colour="black",  linewidth=0.7) +
  xa + labs(tag="D", x="Year", y="Chow F",
    subtitle="Structural-break sweep, old (grey) vs new normalised (black)") + house

fig <- pcmp / prate / pc1cmp / pchow
ggsave("lords_official_rebuild/fig_lords_rebuild_comparison.png", fig,
       width=8.5, height=12, dpi=200, bg="white")
